if mibBuilder.loadTexts: c802tapStreamEntry.setStatus('current')
if mibBuilder.loadTexts: c802tapStreamEntry.setDescription('A stream entry indicates a single data stream to be\n        intercepted to a Mediation Device. Many selected data\n        streams may go to the same application interface, and many\n        application interfaces are supported.')
